<script setup lang="ts">
import { vDialogFocus } from './dialog-focus'
import {computed,ref} from 'vue'
import {CalendarClock,Pause,Play,Square,Plus} from '@lucide/vue'
defineProps<{scenario:string}>()
const editing=ref(false),kind=ref('Once'),zone=ref('Asia/Shanghai'),misfire=ref('Coalesce once'),consent=ref(false),saved=ref(false),paused=ref(false),stopped=ref(false),feedback=ref(''),hour=ref('09:00'),limit=ref(3)
const rules=['Once','After duration','Fixed interval','Daily','Weekly']
const savedPlan=ref({kind:'Once',zone:'Asia/Shanghai',time:'09:00',limit:1,misfire:'Coalesce once'})
const occurrences=computed(()=>recurring.value?limit.value:1)
const recurring=computed(()=>!['Once','After duration'].includes(kind.value))
function save(){if(!consent.value)return;savedPlan.value={kind:kind.value,zone:zone.value,time:hour.value,limit:occurrences.value,misfire:misfire.value};saved.value=true;paused.value=false;stopped.value=false;editing.value=false;feedback.value='Fixture schedule saved. No daemon timer or model call was created.'}
</script>
<template><section class="nx-preview"><div class="pv-heading nx-heading"><div><p class="pv-eyebrow">PV-04 / REVISION 1</p><h1>Schedules</h1><p class="pv-muted">Bounded continuations for an explicitly selected task and session.</p></div><button class="btn btn-primary" :disabled="['Read only','Permission denied','Disconnected','Loading'].includes(scenario)" @click="editing=true;consent=false"><Plus :size="16"/>New schedule</button></div>
<div v-if="scenario==='Disconnected'" class="nx-alert">Disconnected. Last saved plan shown; changes are unavailable.</div><div v-if="['Error','Conflict','Changed version'].includes(scenario)" class="nx-alert">The schedule changed or could not be saved. Reload its version before confirming.</div>
<div v-if="!saved||scenario==='Empty'" class="nx-schedule-empty"><CalendarClock :size="32"/><h2>No active schedules</h2><p class="pv-muted">Create a one-time reminder or a bounded recurring continuation.</p></div>
<div v-else class="nx-schedule-card"><div class="pv-between"><span class="nx-icon-label"><CalendarClock :size="20"/><strong>Review validation report</strong></span><span class="pv-badge">{{stopped?'Stopped':paused?'Paused':'Scheduled'}}</span></div><dl class="nx-details"><dt>Rule</dt><dd>{{savedPlan.kind}} · {{savedPlan.time}} · {{savedPlan.zone}}</dd><dt>Next occurrence</dt><dd>{{stopped||paused?'Not scheduled':'Calculated by daemon after confirmation'}}</dd><dt>Missed triggers</dt><dd>{{savedPlan.misfire}} · no unlimited catch-up</dd><dt>Stop condition</dt><dd>{{savedPlan.limit}} occurrences · 12,000 tokens maximum</dd><dt>Bound session</dt><dd>Current session · task-07 · generation 1</dd></dl><div class="pv-actions"><button class="btn" :disabled="stopped||scenario==='Disconnected'" @click="paused=!paused"><Play v-if="paused" :size="15"/><Pause v-else :size="15"/>{{paused?'Resume':'Pause'}}</button><button class="btn" :disabled="stopped||scenario==='Disconnected'" @click="editing=true;consent=false">Edit plan</button><button class="btn nx-danger" :disabled="stopped||scenario==='Disconnected'" @click="stopped=true;feedback='Future occurrences invalidated. An already active turn is controlled separately.'"><Square :size="14"/>Cancel future occurrences</button></div></div>
<p v-if="feedback" role="status" class="nx-feedback">{{feedback}}</p>
<div v-if="editing" class="pv-overlay" @click.self="editing=false" @keydown.esc="editing=false"><section v-dialog-focus class="pv-modal nx-schedule-editor" role="dialog" aria-modal="true" aria-label="Schedule plan"><div class="pv-between"><h2>Schedule a continuation</h2><button class="btn" aria-label="Close editor" @click="editing=false">Close</button></div><div class="nx-form"><label>Rule<select v-model="kind" class="input"><option v-for="k in rules" :key="k">{{k}}</option></select></label><label>Time zone<select v-model="zone" class="input"><option>Asia/Shanghai</option><option>UTC</option><option>America/New_York</option></select></label><label v-if="kind==='Once'">Date<input class="input" type="date" value="2026-10-16"/></label><label v-if="kind==='Weekly'">Weekday<select class="input"><option>Monday</option><option>Tuesday</option><option>Wednesday</option><option>Thursday</option><option>Friday</option><option>Saturday</option><option>Sunday</option></select></label><label v-if="kind==='After duration'||kind==='Fixed interval'">{{kind==='After duration'?'Wait minutes':'Interval minutes'}}<input class="input" type="number" min="1" value="30"/></label><label v-else>Local time<input v-model="hour" type="time" class="input"/></label><label>Missed triggers<select v-model="misfire" class="input"><option>Coalesce once</option><option>Skip</option></select></label><label v-if="recurring">Maximum occurrences<input v-model="limit" class="input" type="number" min="1" max="20"/></label></div><div class="nx-callout"><strong>{{recurring?'Recurring continuation':'One-time continuation'}}</strong><p>Review validation report in the current session. Use existing permissions, up to {{occurrences}} occurrences and 12,000 tokens. A new user message or changed permissions blocks stale continuation.</p><p class="pv-muted">Requires a running daemon and open workspace. Skipped DST times are omitted; repeated local times run once. Closing the workspace pauses its schedule.</p></div><label class="nx-consent"><input v-model="consent" type="checkbox"/>Allow this exact plan and bounded automatic continuation</label><div class="pv-actions"><button class="btn" @click="editing=false">Cancel</button><button class="btn btn-primary" :disabled="!consent||limit<1||limit>20" @click="save">Confirm fixture plan</button></div></section></div>
</section></template>
